import { cn } from "@/lib/utils";
import { EMBLEM_BOX, EMBLEM_G_PATH, EMBLEM_STROKE, EMBLEM_U_PATH, WORDMARK } from "./brand-geometry";

// USOPGRID identity: single source of truth for the brand in the app.
//
// Emblem: a square geometric G frame enclosing a U; the G's inner bar meets
// the U's right stem at one junction (structured connectivity, one dependable
// route). Antique Gold on Institutional Navy. Geometry and wordmark outlines
// are generated by scripts/brand/generate.py together with public/brand/*.svg.
// Rules: gold emblem only on navy (bare on dark surfaces, inside the navy
// tile on light surfaces); never gold text on light backgrounds; no
// gradients, shadows or metallic effects.

export const USOPGRID_NAME = "USOPGRID";
export const USOPGRID_TAGLINE = "Powering Every Payment Connection.";
export const USOPGRID_DESCRIPTOR = "Enterprise Payment Infrastructure";
export const USOPGRID_COMPANY = "RAE Horizon Technologies Limited";

/** Official palette. */
export const BRAND = {
  navy: "#142746", // Primary Institutional Navy
  midnight: "#0B1930", // Deep Midnight Navy
  gold: "#C5A15D", // Antique Gold
  champagne: "#D6BC82", // Champagne Gold
  ivory: "#F7F5EF", // Ivory White
  charcoal: "#292D32", // Charcoal
  warmGrey: "#D8D5CD", // Warm Grey
  /** Gold darkened for text and thin rules on light surfaces (AA on ivory). */
  goldInk: "#7F6128",
} as const;

export type EmblemTone =
  /** Navy tile with gold emblem. Use on light surfaces and as the app icon. */
  | "tile"
  /** Bare gold emblem. Use on navy/midnight surfaces. */
  | "onDark"
  /** Alias of "tile" kept for existing call sites on light surfaces. */
  | "onLight"
  /** Single colour (currentColor) for documents, stamps, watermarks. */
  | "mono";

function Strokes({ color }: { color: string }) {
  return (
    <>
      <path d={EMBLEM_G_PATH} fill="none" stroke={color} strokeWidth={EMBLEM_STROKE} strokeLinecap="butt" strokeLinejoin="miter" />
      <path d={EMBLEM_U_PATH} fill="none" stroke={color} strokeWidth={EMBLEM_STROKE} strokeLinecap="butt" strokeLinejoin="miter" />
    </>
  );
}

export function UsopgridMark({
  className,
  tone = "tile",
  title = USOPGRID_NAME,
}: {
  className?: string;
  tone?: EmblemTone;
  title?: string;
}) {
  if (tone === "onDark" || tone === "mono") {
    const { x, y, w, h } = EMBLEM_BOX;
    // Bare emblem: square box so it lines up with tile marks at the same size.
    const side = Math.max(w, h);
    return (
      <svg viewBox={`${x - (side - w) / 2} ${y - (side - h) / 2} ${side} ${side}`} xmlns="http://www.w3.org/2000/svg" role="img" aria-label={title} className={cn("shrink-0", className)}>
        <Strokes color={tone === "mono" ? "currentColor" : BRAND.gold} />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg" role="img" aria-label={title} className={cn("shrink-0", className)}>
      <rect width="64" height="64" rx="6" fill={BRAND.navy} />
      <g transform="translate(32 32) scale(0.74) translate(-32 -32)">
        <Strokes color={BRAND.gold} />
      </g>
    </svg>
  );
}

/** The USOPGRID wordmark as outlines; height follows font-size (1em = cap height × 1.0). */
export function UsopgridWordmark({ className, color = "currentColor" }: { className?: string; color?: string }) {
  const s = 1 / WORDMARK.cap;
  const w = WORDMARK.width * s;
  return (
    <svg viewBox={`0 -1 ${w} 1`} xmlns="http://www.w3.org/2000/svg" role="img" aria-label={USOPGRID_NAME} className={cn("h-[0.72em] w-auto shrink-0 overflow-visible", className)}>
      <path transform={`translate(${-WORDMARK.minX * s} 0) scale(${s})`} d={WORDMARK.d} fill={color} />
    </svg>
  );
}

/** Lockup: emblem + wordmark, horizontal (default) or vertical. */
export function UsopgridLogo({
  className,
  markClassName,
  wordClassName,
  tone = "tile",
  layout = "horizontal",
}: {
  className?: string;
  markClassName?: string;
  wordClassName?: string;
  tone?: EmblemTone;
  layout?: "horizontal" | "vertical";
}) {
  const wordColor = tone === "onDark" ? BRAND.ivory : tone === "mono" ? "currentColor" : BRAND.navy;
  return (
    <span
      className={cn(
        layout === "vertical" ? "inline-flex flex-col items-center gap-3" : "inline-flex items-center gap-3",
        className,
      )}
      aria-label={USOPGRID_NAME}
      role="img"
    >
      <UsopgridMark tone={tone} title="" className={cn(layout === "vertical" ? "size-14" : "size-8", markClassName)} />
      <UsopgridWordmark color={wordColor} className={cn(layout === "vertical" ? "text-[26px]" : "text-[19px]", wordClassName)} />
    </span>
  );
}
